output_text:
[
  {
    "id": "must_get_cart",
    "text": "Shoppers are obligated to obtain a cart before completing their trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Shoppers are prohibited from exiting the store unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_for_required_item_interactions",
    "text": "Shoppers are prohibited from interacting with the item shelves at the demonstrated item locations unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "hasCart"
          },
          {
            "or": [
              "at(6,6)",
              "at(9,6)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_main_aisle_without_cart",
    "text": "Shoppers are prohibited from being in the main shopping aisle without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "at(1,6)",
              "at(2,6)",
              "at(3,6)",
              "at(4,6)",
              "at(5,6)",
              "at(6,6)",
              "at(7,6)",
              "at(8,6)",
              "at(9,6)",
              "at(10,6)",
              "at(11,6)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "take_cart_at_cart_area",
    "text": "A shopper who reaches the cart area is obligated to take a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "at(1,7)",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_wrong_exit_cell",
    "text": "Shoppers are prohibited from using EXIT anywhere except the designated exit cell.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "at(11,7)"
          }
        ]
      }
    }
  },
  {
    "id": "no_north_without_cart",
    "text": "Shoppers are prohibited from moving north into the store unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "N",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_west",
    "text": "Shoppers are prohibited from moving west, as if the aisles are one-way.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
